record.field:
                {
                "apiVersion": "dashboard.grafana.app/v2",
                "kind": "Dashboard",
                "metadata": {
                    "name": "estadisticas-usos-del-agua"
                },
                "spec": {
                    "annotations": [
                    {
                        "kind": "AnnotationQuery",
                        "spec": {
                        "query": {
                            "kind": "DataQuery",
                            "group": "grafana",
                            "version": "v0",
                            "datasource": {
                            "name": "-- Grafana --"
                            },
                            "spec": {}
                        },
                        "enable": true,
                        "hide": true,
                        "iconColor": "rgba(0, 211, 255, 1)",
                        "name": "Annotations & Alerts",
                        "builtIn": true,
                        "legacyOptions": {
                            "type": "dashboard"
                        }
                        }
                    }
                    ],
                    "cursorSync": "Off",
                    "editable": true,
                    "elements": {
                    "panel-1": {
                        "kind": "Panel",
                        "spec": {
                        "id": 1,
                        "title": "",
                        "links": [],
                        "data": {
                            "kind": "QueryGroup",
                            "spec": {
                            "queries": [
                                {
                                "kind": "PanelQuery",
                                "spec": {
                                    "query": {
                                    "kind": "DataQuery",
                                    "group": "grafana-postgresql-datasource",
                                    "version": "v0",
                                    "spec": {
                                        "editorMode": "code",
                                        "format": "table",
                                        "rawQuery": true,
                                        "rawSql": "-- =============================================================================
-- Panel     : distribución de cultivos (sin título) · id 1 · ref A · table → Business Charts
-- Propósito : porcentaje de la superficie cultivada de la zona regable que ocupa cada uso SIGPAC.
-- Entradas  : ninguna; no usa el rango de tiempo del panel
-- Salida    : Codigo (uso SIGPAC o RESTO; fija el color de la barra), Cultivo (nombre),
--             Porcentaje (% sobre la superficie cultivada, 2 decimales),
--             Incluye (solo en RESTO: «nombre=porcentaje» separados por «;»; NULL en el resto)
-- Notas     : zona regable = parcelas de Odoo; superficie = intersección parcela ∩ recinto SIGPAC
--             (vista materializada wua_parcel_sigpaclink, datos del último refresco).
--             Usos cultivados según el catálogo cod_uso_sigpac; CO (contorno olivar) se suma a OV.
--             Fuera: tierra arable, pastos, forestal, matorral, improductivo, urbano, viales, agua…
--             Los usos con menos del 1 % se agrupan en RESTO, que sale siempre la última.
-- =============================================================================
WITH
-- Fuentes ---------------------------------------------------------------------
usos_cultivados AS (
  -- Superficie (ha) por uso SIGPAC cultivado
  SELECT
    CASE WHEN uso_sigpac = 'CO' THEN 'OV' ELSE uso_sigpac END AS codigo,
    sum(area_ha) AS ha
  FROM wua_parcel_sigpaclink
  WHERE uso_sigpac IN (
    'VI', 'OV', 'CO', 'FS', 'FY', 'CI', 'CF', 'CS', 'CV', 'FF',
    'FL', 'FV', 'OC', 'OF', 'VF', 'VO', 'OP', 'TH', 'IV'
  )
  GROUP BY 1
),
-- Transformaciones ------------------------------------------------------------
cultivos AS (
  -- Nombre de cada uso y su porcentaje sobre el total cultivado
  SELECT
    codigo,
    CASE codigo
      WHEN 'VI' THEN 'Viñedo'
      WHEN 'OV' THEN 'Olivar'
      WHEN 'FS' THEN 'Frutos secos'
      WHEN 'FY' THEN 'Frutales'
      WHEN 'CI' THEN 'Cítricos'
      WHEN 'TH' THEN 'Huerta'
      WHEN 'IV' THEN 'Invernaderos y cultivos bajo plástico'
      WHEN 'OP' THEN 'Otros cultivos permanentes'
      WHEN 'VO' THEN 'Viñedo y olivar'
      WHEN 'VF' THEN 'Viñedo y frutales'
      WHEN 'FF' THEN 'Frutales y frutales de cáscara'
      WHEN 'FV' THEN 'Frutos secos y viñedo'
      WHEN 'FL' THEN 'Frutos secos y olivar'
      WHEN 'OF' THEN 'Olivar y frutales'
      WHEN 'OC' THEN 'Olivar y cítricos'
      WHEN 'CF' THEN 'Cítricos y frutales'
      WHEN 'CS' THEN 'Cítricos y frutales de cáscara'
      WHEN 'CV' THEN 'Cítricos y viñedo'
      ELSE codigo
    END AS cultivo,
    ha,
    100.0 * ha / sum(ha) OVER () AS pct
  FROM usos_cultivados
),
-- Agregados -------------------------------------------------------------------
agrupados AS (
  -- Usos por debajo del 1 % reunidos en RESTO, con el detalle de lo agrupado
  SELECT
    CASE WHEN pct < 1 THEN 'RESTO' ELSE codigo END AS codigo,
    CASE WHEN pct < 1 THEN 'Resto de cultivos' ELSE cultivo END AS cultivo,
    sum(ha) AS ha,
    sum(pct) AS pct,
    string_agg(cultivo || '=' || round(pct::numeric, 2), ';' ORDER BY pct DESC)
      FILTER (WHERE pct < 1) AS incluye
  FROM cultivos
  GROUP BY 1, 2
)
-- Salida ----------------------------------------------------------------------
SELECT
  codigo AS "Codigo",
  cultivo AS "Cultivo",
  round(pct::numeric, 2) AS "Porcentaje",
  incluye AS "Incluye"
FROM agrupados
ORDER BY
  (codigo = 'RESTO'),
  ha DESC"
                                    },
                                    "labels": {
                                        "grafana.app/export-label": "grafana-postgresql-datasource-1"
                                    }
                                    },
                                    "refId": "A",
                                    "hidden": false
                                }
                                }
                            ],
                            "transformations": [],
                            "queryOptions": {}
                            }
                        },
                        "vizConfig": {
                            "kind": "VizConfig",
                            "group": "volkovlabs-echarts-panel",
                            "version": "",
                            "spec": {
                            "options": {
                                "editor": {
                                "format": "auto",
                                "language": "javascript"
                                },
                                "editorMode": "code",
                                "getOption": "// =============================================================================
// Panel 1 · Distribución de cultivos en la zona regable (Business Charts, sin título)
// Campos: Codigo, Cultivo, Porcentaje, Incluye (ver la cabecera de la consulta A)
// Barras con el % de cada uso SIGPAC cultivado, color fijo por uso y línea al pie
// que explica qué agrupa «Resto de cultivos».
// =============================================================================

// --- Datos de la consulta (format table) -------------------------------------
const frame = context.panel.data.series.find(s => s.fields.some(f => f.name === 'Cultivo'));
if (!frame || !frame.length) return {
  title: {
    text: 'Sin datos SIGPAC de la zona regable',
    left: 'center',
    top: 'middle',
    textStyle: { color: '#81968a', fontSize: 14, fontWeight: 500 }
  }
};
const col = n => Array.from(frame.fields.find(f => f.name === n).values);
const names = col('Cultivo');
const pct = col('Porcentaje').map(Number);

// --- Utilidades y estilo común -----------------------------------------------
// Color fijo por uso SIGPAC (igual en todas las instancias).
// Puros: color del cultivo; asociaciones: mezcla de sus dos cultivos.
const COLOR = {
  VI: '#6B2D5C', OV: '#6B7F2A', FS: '#8B5A2B', FY: '#C0504D', CI: '#F2A743', TH: '#4E9F64', IV: '#8FA9B8',
  OP: '#A68A64',
  VO: '#6D5644', VF: '#963F55', FV: '#7B4440', FL: '#7B6D2B', FF: '#A6553C', OF: '#96683C', OC: '#AF9337',
  CF: '#D97B48', CS: '#BE8137', CV: '#AE6A50', RESTO: '#A1B6AD'
};
const codF = frame.fields.find(f => f.name === 'Codigo');
const cods = codF ? Array.from(codF.values) : [];
// Código no previsto en COLOR: gris verdoso neutro
const colorOf = (n, i) => COLOR[cods[i]] || (n === 'Resto de cultivos' ? COLOR.RESTO : '#8CA99F');
// Etiquetas del eje partidas en dos líneas para los nombres largos más habituales
const short = {
  'Invernaderos y cultivos bajo plástico': 'Invernaderos',
  'Otros cultivos permanentes': 'Otros cultivos\npermanentes',
  'Frutales y frutales de cáscara': 'Frutales y\nfrutos de cáscara',
  'Viñedo y olivar': 'Viñedo y\nolivar',
  'Viñedo y frutales': 'Viñedo y\nfrutales',
  'Frutos secos': 'Frut. secos',
  'Cítricos y frutales': 'Cítric/Frut.',
  'Resto de cultivos': 'Resto de\ncultivos (<1 %)'
};
const nf = d => new Intl.NumberFormat('es-ES', { minimumFractionDigits: d, maximumFractionDigits: d });
const fmtP = v => v > 0 && v < 0.01 ? '<0,01 %' : nf(2).format(v) + ' %';

// --- Preparación -------------------------------------------------------------
// Eje Y: máximo + 5 %, redondeado a la decena (mínimo 10 %)
const yMax = Math.max(10, Math.ceil((Math.max(...pct) + 5) / 10) * 10);
// Línea explicativa de «Resto de cultivos», construida con los datos (nada fijo).
// Incluye llega como «nombre=porcentaje» separados por «;».
const incF = frame.fields.find(f => f.name === 'Incluye');
const inc = incF ? Array.from(incF.values) : [];
const ri = names.indexOf('Resto de cultivos');
const restItems = ri >= 0 && inc[ri] ? String(inc[ri]).split(';').map(s => {
  const [n, p] = s.split('=');
  return { n, p: Number(p) };
}) : [];
const joinY = a => a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' y ' + a[a.length - 1];
const restLine = restItems.length
  ? '«Resto de cultivos» agrupa los usos SIGPAC con menos del 1 % de la superficie cultivada: '
    + joinY(restItems.map(x => x.n + ' (' + fmtP(x.p) + ')')) + '.'
  : '';
const chartW = (context.panel.chart && context.panel.chart.getWidth && context.panel.chart.getWidth()) || 900;

// --- Opciones ECharts --------------------------------------------------------
return {
  graphic: restLine ? [{
    type: 'text',
    left: 20,
    bottom: 6,
    style: {
      text: restLine,
      width: chartW - 40,
      overflow: 'break',
      lineHeight: 16,
      fill: '#6f8a7c',
      fontSize: 11,
      fontFamily: 'Inter, Arial, sans-serif'
    }
  }] : [],
  backgroundColor: 'transparent',
  animationDuration: 700,
  textStyle: { fontFamily: 'Inter, Arial, sans-serif', color: '#35564a' },
  grid: { left: 54, right: 26, top: 52, bottom: restLine ? 40 : 12, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(36,107,83,0.04)' } },
    backgroundColor: '#ffffff',
    borderColor: '#dde7e1',
    padding: 14,
    textStyle: { color: '#254e3d', fontSize: 13 },
    formatter: p => {
      const i = p[0].dataIndex;
      let t = names[i] + '<br/><strong>' + fmtP(pct[i]) + '</strong> de la superficie cultivada';
      if (i === ri && restItems.length) t += '<br/><span style="color:#6f8a7c;font-size:12px">'
        + restItems.map(x => x.n + ': ' + fmtP(x.p)).join('<br/>') + '</span>';
      return t;
    }
  },
  xAxis: {
    type: 'category',
    data: names,
    axisLine: { lineStyle: { color: '#dce6df' } },
    axisTick: { show: false },
    axisLabel: {
      interval: 0,
      fontSize: 11,
      lineHeight: 16,
      margin: 16,
      color: '#456454',
      formatter: n => short[n] || (n.length > 14 ? n.replace(' y ', '\ny ') : n)
    }
  },
  yAxis: {
    type: 'value',
    min: 0,
    max: yMax,
    interval: 10,
    name: 'Superficie cultivada · %',
    nameTextStyle: { color: '#81968a', fontSize: 11, padding: [0, 0, 16, 0] },
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: { formatter: '{value} %', color: '#8a9e92', fontSize: 11 },
    splitLine: { lineStyle: { color: '#edf2ee', type: 'dashed' } }
  },
  series: [{
    name: 'Porcentaje de superficie cultivada',
    type: 'bar',
    barMaxWidth: 120,
    barCategoryGap: '22%',
    barMinHeight: 2,
    data: pct.map((value, i) => {
      const c = colorOf(names[i], i);
      return {
        value,
        itemStyle: {
          color: new context.echarts.graphic.LinearGradient(0, 0, 0, 1, [
            { offset: 0, color: c },
            { offset: 1, color: c + 'bb' }
          ]),
          borderRadius: [8, 8, 0, 0]
        }
      };
    }),
    label: {
      show: true,
      position: 'top',
      distance: 12,
      color: '#254e3d',
      fontWeight: 600,
      fontSize: 13,
      formatter: p => fmtP(p.value)
    },
    emphasis: { itemStyle: { shadowBlur: 15, shadowColor: 'rgba(31,78,61,.12)' } }
  }],
  aria: {
    enabled: true,
    // Cadena literal larga: se deja en una línea (excepción al límite de 120 caracteres, guía §2.1)
    description: 'Distribución de los cultivos de la zona regable (SIGPAC) como porcentaje de la superficie cultivada; sin tierra arable, pastos ni usos no agrícolas.'
  }
};",
                                "renderer": "svg"
                            },
                            "fieldConfig": {
                                "defaults": {},
                                "overrides": []
                            }
                            }
                        }
                        }
                    },
                    "panel-10": {
                        "kind": "Panel",
                        "spec": {
                        "id": 10,
                        "title": "",
                        "links": [],
                        "data": {
                            "kind": "QueryGroup",
                            "spec": {
                            "queries": [
                                {
                                "kind": "PanelQuery",
                                "spec": {
                                    "query": {
                                    "kind": "DataQuery",
                                    "group": "grafana-postgresql-datasource",
                                    "version": "v0",
                                    "spec": {
                                        "editorMode": "code",
                                        "format": "table",
                                        "rawQuery": true,
                                        "rawSql": "-- =============================================================================
-- Panel     : cabecera · id 10 · ref A · table → Business Text
-- Propósito : nombre de la comunidad (compañía de Odoo) para la banda de cabecera.
-- Entradas  : ninguna; no usa el rango de tiempo del panel
-- Salida    : comunidad (texto en mayúsculas)
-- Notas     : si hay varias compañías, la de id más bajo.
-- =============================================================================
SELECT
  upper(name) AS comunidad
FROM res_company
ORDER BY id
LIMIT 1"
                                    },
                                    "labels": {
                                        "grafana.app/export-label": "grafana-postgresql-datasource-1"
                                    }
                                    },
                                    "refId": "A",
                                    "hidden": false
                                }
                                }
                            ],
                            "transformations": [],
                            "queryOptions": {}
                            }
                        },
                        "vizConfig": {
                            "kind": "VizConfig",
                            "group": "marcusolsson-dynamictext-panel",
                            "version": "",
                            "spec": {
                            "options": {
                                "afterRender": "",
                                "content": "{{!-- Campos de la consulta A: comunidad --}}<div class="water-heading"><div class="water-mark">{{comunidad}} <span>·</span> SUPERFICIE CULTIVADA · SIGPAC</div><div class="water-bottom"><h1>Estadísticas sobre el uso del agua</h1></div></div>",
                                "contentPartials": [],
                                "defaultContent": "<div class="water-heading"><div class="water-mark">SIN DATOS SIGPAC</div><h1>Estadísticas sobre el uso del agua</h1></div>",
                                "editors": [
                                "styles"
                                ],
                                "renderMode": "everyRow",
                                "styles": "/* =============================================================================
   Panel 10 · cabecera (Business Text) · plantilla: .water-heading > .water-mark + .water-bottom > h1
   ============================================================================= */
.water-heading{box-sizing:border-box;padding:14px 26px;background:linear-gradient(110deg,#173e31,#28634e);
  border-radius:14px;color:#fff;font-family:Inter,Arial,sans-serif;min-height:0}
.water-mark{font-size:10px;font-weight:600;letter-spacing:2px;color:#a6cfba}
.water-mark span{margin:0 8px;color:#85ba9b}
.water-heading h1{margin:7px 0 0;font-size:clamp(20px,2.5vw,28px);font-weight:600;letter-spacing:-.7px;line-height:1.2}
.water-bottom{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap}
/* Reglas para un subtítulo <p> en .water-bottom: la plantilla actual no lo usa (se quitaron las cifras) */
.water-bottom p{margin:0 0 4px;font-size:12px;color:#d4e7db}
.water-bottom p span{margin:0 8px;color:#9bc6ad}",
                                "wrap": false
                            },
