                            }
                        }
                        }
                    },
                    "panel-21": {
                        "kind": "Panel",
                        "spec": {
                        "id": 21,
                        "title": "Calendario de ET₀ y Precipitación Efectiva",
                        "links": [],
                        "data": {
                            "kind": "QueryGroup",
                            "spec": {
                            "queries": [
                                {
                                "kind": "PanelQuery",
                                "spec": {
                                    "query": {
                                    "kind": "DataQuery",
                                    "group": "grafana-postgresql-datasource",
                                    "version": "v0",
                                    "spec": {
                                        "editorMode": "code",
                                        "format": "table",
                                        "rawQuery": true,
                                        "rawSql": "-- =============================================================================
-- Panel     : Calendario de ET₀ y Precipitación Efectiva · id 21 · ref A · table → Business Charts
-- Propósito : ET0 y precipitación efectiva diarias del año hidrológico en curso (SIAR).
-- Entradas  : ninguna; año hidrológico en curso según la fecha actual (Europe/Madrid);
--             no usa variables (el dashboard público no las sustituye) ni el rango de tiempo del panel
-- Salida    : dia (texto AAAA-MM-DD), et0 (mm, 2 decimales, atípicas sustituidas),
--             pe (mm, 2 decimales), anom (true si la ET0 del día era atípica)
-- Notas     : estaciones SIAR = dispositivos activos cuyo telecontrol contiene «SIAR» en el nombre;
--             sensores por nombre, sin ids fijos; media de todas las estaciones.
--             ET0 atípica por estación (> 12 mm o > max(4, 4 × mediana del mes)) sustituida por la media
--             del mes sin atípicos. 0 filas si no hay estaciones SIAR o lecturas en el año.
-- =============================================================================
WITH
-- Parámetros ------------------------------------------------------------------
periodo AS (
  -- [bloque periodo_hy] Año hidrológico en curso: del 1 de octubre al 30 de septiembre (fin exclusivo).
  --   Año de inicio = año actual si el mes es octubre o posterior; si no, año anterior.
  SELECT
    make_date(a.hy, 10, 1) AS inicio,
    make_date(a.hy + 1, 10, 1) AS fin
  FROM (
    SELECT
      extract(year FROM h.hoy)::int - CASE WHEN extract(month FROM h.hoy) >= 10 THEN 0 ELSE 1 END AS hy
    FROM (SELECT (now() AT TIME ZONE 'Europe/Madrid')::date AS hoy) h
  ) a
),
-- Fuentes ---------------------------------------------------------------------
-- [bloque estaciones_siar] Dispositivos activos cuyo telecontrol se llama «…SIAR…»
--   (en Odoo el tipo de telecontrol es genérico, rest; el nombre es la única marca).
estaciones AS (
  SELECT
    d.id AS dispositivo
  FROM mdm_measurement_device d
  JOIN remotecontrol t ON t.id = d.remotecontrol_id
  WHERE d.active
    AND t.name ILIKE '%siar%'
),
-- [bloque siar_diario] Sensores Et0 y Pe de las estaciones SIAR, por nombre.
sensores AS (
  SELECT
    s.id AS sensor,
    s.device_id AS dispositivo,
    lower(s.name) AS variable
  FROM mdm_measurement_device_sensor s
  JOIN estaciones e ON e.dispositivo = s.device_id
  WHERE s.active
    AND lower(s.name) IN ('et0', 'pe')
),
-- [bloque siar_diario] Valor diario por estación (día natural de Madrid); la lectura en UTC se pide
--   con un día de margen a cada lado para no perder bordes por la conversión a hora local.
lecturas_dia AS (
  SELECT
    sn.dispositivo,
    ((r.measurement_time AT TIME ZONE 'UTC') AT TIME ZONE 'Europe/Madrid')::date AS dia,
    max(r.value) FILTER (WHERE sn.variable = 'et0') AS et0,
    max(r.value) FILTER (WHERE sn.variable = 'pe') AS pe
  FROM mdm_measurement_device_sensor_reading r
  JOIN sensores sn ON sn.sensor = r.sensor_id
  WHERE r.active
    AND r.measurement_time >= (SELECT inicio - 1 FROM periodo)
    AND r.measurement_time < (SELECT fin + 1 FROM periodo)
  GROUP BY 1, 2
),
-- Transformaciones ------------------------------------------------------------
-- [bloque siar_diario] Días dentro del año hidrológico
dias_periodo AS (
  SELECT
    l.dispositivo,
    l.dia,
    l.et0,
    l.pe
  FROM lecturas_dia l
  CROSS JOIN periodo p
  WHERE l.dia >= p.inicio
    AND l.dia < p.fin
),
-- [bloque siar_diario] Mediana mensual de ET0 por estación, para detectar valores atípicos
mediana_mes AS (
  SELECT
    dispositivo,
    date_trunc('month', dia) AS mes,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY et0) AS mediana
  FROM dias_periodo
  GROUP BY 1, 2
),
-- [bloque siar_diario] ET0 atípica: > 12 mm o > max(4, 4 × mediana del mes); sin ET0 → no atípica
marcados AS (
  SELECT
    dp.dispositivo,
    dp.dia,
    dp.et0,
    dp.pe,
    coalesce(dp.et0 > 12 OR dp.et0 > greatest(4, 4 * mm.mediana), false) AS anom
  FROM dias_periodo dp
  JOIN mediana_mes mm
    ON mm.dispositivo = dp.dispositivo
    AND mm.mes = date_trunc('month', dp.dia)
),
-- [bloque siar_diario] Media mensual de ET0 sin atípicos, por estación
media_mes AS (
  SELECT
    dispositivo,
    date_trunc('month', dia) AS mes,
    avg(et0) FILTER (WHERE NOT anom) AS media
  FROM marcados
  GROUP BY 1, 2
),
-- [bloque siar_diario] ET0 atípica sustituida por la media del mes de su estación
corregidos AS (
  SELECT
    m.dispositivo,
    m.dia,
    CASE WHEN m.anom THEN me.media ELSE m.et0 END AS et0,
    m.pe,
    m.anom
  FROM marcados m
  JOIN media_mes me
    ON me.dispositivo = m.dispositivo
    AND me.mes = date_trunc('month', m.dia)
),
-- Agregados -------------------------------------------------------------------
-- [bloque siar_diario] Media diaria de todas las estaciones SIAR; anom si alguna estación lo era
diario AS (
  SELECT
    dia,
    avg(et0) AS et0,
    avg(pe) AS pe,
    bool_or(anom) AS anom
  FROM corregidos
  GROUP BY 1
)
-- Salida ----------------------------------------------------------------------
SELECT
  to_char(dia, 'YYYY-MM-DD') AS dia,
  round(et0::numeric, 2) AS et0,
  round(pe::numeric, 2) AS pe,
  anom
FROM diario
ORDER BY dia"
                                    },
                                    "labels": {
                                        "grafana.app/export-label": "grafana-postgresql-datasource-1"
                                    }
                                    },
                                    "refId": "A",
                                    "hidden": false
                                }
                                }
                            ],
                            "transformations": [],
                            "queryOptions": {}
                            }
                        },
                        "vizConfig": {
                            "kind": "VizConfig",
                            "group": "volkovlabs-echarts-panel",
                            "version": "",
                            "spec": {
                            "options": {
                                "editor": {
                                "format": "auto",
                                "language": "javascript"
                                },
                                "editorMode": "code",
                                "getOption": "// =============================================================================
// Panel 21 · Calendario de ET₀ y Precipitación Efectiva (Business Charts)
// Campos: dia, et0, pe, anom (ver la cabecera de la consulta A)
// Calendario de 3 meses: color = ET0 diaria; gris oscuro = ET0 atípica sustituida;
// puntos azules = precipitación efectiva ≥ 1 mm.
// =============================================================================

// --- Datos de la consulta (format table) -------------------------------------
const f = context.panel.data.series.find(s => s.fields.some(x => x.name === 'dia'));
const g = n => (f && f.fields.find(x => x.name === n) ? Array.from(f.fields.find(x => x.name === n).values) : []);
const dia = g('dia'),
  et0 = g('et0').map(v => v == null ? null : Number(v)),
  pe = g('pe').map(v => v == null ? null : Number(v)),
  anom = g('anom');
// Año hidrológico de la variable oculta hy; si no se puede leer, el año hidrológico en curso
let hy = parseInt(
  context.grafana && context.grafana.replaceVariables ? context.grafana.replaceVariables('${hy}') : '',
  10
);
if (!Number.isFinite(hy)) {
  const n = new Date();
  hy = n.getMonth() >= 9 ? n.getFullYear() : n.getFullYear() - 1;
}
if (!dia.length) return {
  title: {
    text: 'Sin datos SIAR en el año hidrológico ' + hy + '-' + (hy + 1),
    left: 'center',
    top: 'middle',
    textStyle: { color: '#81968a', fontSize: 14, fontWeight: 500 }
  }
};

// --- Utilidades y estilo común -----------------------------------------------
const fmt = (x, d) => x == null
  ? '—'
  : Number(x).toLocaleString('es-ES', { minimumFractionDigits: d, maximumFractionDigits: d });
// [bloque ventana_3_meses] Igual en los paneles 21 y 23.
// Ventana de 3 meses: termina hoy (o el 30 sep si el año ya terminó);
// si desde el 1 oct aún no han pasado 3 meses, del 1 oct al 31 dic.
const pad = n => String(n).padStart(2, '0');
const iso = d => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const hyStart = new Date(hy, 9, 1),
  hyEnd = new Date(hy + 1, 8, 30);
let wEnd = today < hyEnd ? today : hyEnd;
let wStart = new Date(wEnd.getFullYear(), wEnd.getMonth() - 3, wEnd.getDate() + 1);
if (wStart < hyStart) {
  wStart = hyStart;
  wEnd = new Date(hy, 12, 0);
}
const a = iso(wStart),
  b = iso(wEnd);
const inW = k => k >= a && k <= b;

// --- Preparación -------------------------------------------------------------
// Días de la ventana con ET0: normales (escala de color) y atípicos (gris oscuro)
const ok = dia.map((d, i) => [d, et0[i]]).filter((p, i) => p[1] != null && !anom[i] && inW(p[0]));
const bad = dia.map((d, i) => [d, et0[i]]).filter((p, i) => p[1] != null && anom[i] && inW(p[0]));
const maxE = Math.ceil(Math.max(1, ...ok.map(p => p[1])));
// Búsqueda por día para el tooltip
const peMap = {},
  anMap = {};
dia.forEach((d, i) => {
  peMap[d] = pe[i];
  anMap[d] = !!anom[i];
});
const etMap = {};
dia.forEach((d, i) => etMap[d] = et0[i]);

// --- Opciones ECharts --------------------------------------------------------
return {
  backgroundColor: 'transparent',
  textStyle: { fontFamily: 'Inter, Helvetica, Arial, sans-serif' },
  tooltip: {
    backgroundColor: '#fff',
    borderColor: '#C9D6E3',
    textStyle: { color: '#1B2B3A' },
    formatter: p => {
      const k = p.value[0];
      const d = new Date(k + 'T12:00:00').toLocaleDateString('es-ES',
        { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
      return '<b>' + d + '</b><br>ET₀: <b>' + fmt(etMap[k], 1) + ' mm</b>'
        + (anMap[k] ? ' <span style="color:#4D4D4D">(atípica: media del mes)</span>' : '')
        + '<br>Precip. efectiva: <b>' + fmt(peMap[k], 1) + ' mm</b>';
    }
  },
  visualMap: [
    // ET0 normal: escala continua de 0 al máximo de la ventana
    {
      min: 0,
      max: maxE,
      calculable: true,
      orient: 'horizontal',
      left: 'center',
      bottom: 4,
      itemWidth: 12,
      itemHeight: 220,
      text: ['ET₀ alta (mm/día)', 'baja'],
      textStyle: { color: '#5B7690' },
      seriesIndex: 0,
      inRange: { color: ['#FFF7E6', '#FDD49E', '#FC8D59', '#D7301F', '#7F0000'] }
    },
    // ET0 atípica: un solo color, sin leyenda de escala
    { show: false, seriesIndex: 1, type: 'piecewise', pieces: [{ min: -1e9, max: 1e9, color: '#4D4D4D' }] }
  ],
  graphic: bad.length ? [{
    type: 'text',
    right: 20,
    bottom: 8,
    style: { text: '■ Gris oscuro: ET₀ atípica sustituida por la media del mes', fill: '#4D4D4D', fontSize: 11 }
  }] : [],
  calendar: {
    top: 30,
    left: 40,
    right: 20,
    bottom: 50,
    cellSize: ['auto', 22],
    range: [a, b],
    firstDay: 1,
    itemStyle: { color: '#ECEFF3', borderColor: '#fff', borderWidth: 2 },
    splitLine: { lineStyle: { color: '#9FB3C8', width: 1.2 } },
    yearLabel: { show: false },
    dayLabel: { nameMap: ['D', 'L', 'M', 'X', 'J', 'V', 'S'], color: '#8A9BB0', fontSize: 10 },
    monthLabel: {
      nameMap: ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'],
      color: '#33475B',
      fontWeight: 600
    }
  },
  series: [
    { type: 'heatmap', coordinateSystem: 'calendar', data: ok },
    { type: 'heatmap', coordinateSystem: 'calendar', data: bad },
    {
      type: 'scatter',
      coordinateSystem: 'calendar',
      name: 'Precipitación efectiva',
      data: dia.map((d, i) => [d, pe[i]]).filter(p => p[1] != null && p[1] >= 1 && inW(p[0])),
      symbolSize: v => Math.min(14, 4 + Math.sqrt(v[1]) * 2.2),
      itemStyle: { color: '#1F77B4', borderColor: '#fff', borderWidth: 1 }
    }
  ]
};",
                                "renderer": "svg"
                            },
                            "fieldConfig": {
                                "defaults": {},
                                "overrides": []
                            }
                            }
                        }
                        }
                    },
                    "panel-22": {
                        "kind": "Panel",
                        "spec": {
                        "id": 22,
                        "title": "Totales mensuales",
                        "links": [],
                        "data": {
                            "kind": "QueryGroup",
                            "spec": {
                            "queries": [
                                {
                                "kind": "PanelQuery",
                                "spec": {
                                    "query": {
                                    "kind": "DataQuery",
                                    "group": "grafana-postgresql-datasource",
                                    "version": "v0",
                                    "spec": {
                                        "editorMode": "code",
                                        "format": "table",
                                        "rawQuery": true,
                                        "rawSql": "-- =============================================================================
-- Panel     : Totales mensuales · id 22 · ref A · table → Business Text
-- Propósito : ET0 y precipitación efectiva acumuladas por mes del año hidrológico en curso, y total del año.
-- Entradas  : ninguna; año hidrológico en curso según la fecha actual (Europe/Madrid);
--             no usa variables (el dashboard público no las sustituye) ni el rango de tiempo del panel
-- Salida    : mes (texto Ene…Dic, o «Año» en el total), et0 (mm, texto es-ES con 1 decimal o «—»),
--             pe (ídem), dias (días con dato), total (true solo en la fila del año),
--             orden (fecha del mes; ordena las filas, el total va al final),
--             anio_hidrologico (texto AAAA-AAAA, igual en todas las filas)
-- Notas     : estaciones SIAR = dispositivos activos cuyo telecontrol contiene «SIAR» en el nombre;
--             sensores por nombre, sin ids fijos; media de todas las estaciones.
--             ET0 atípica por estación (> 12 mm o > max(4, 4 × mediana del mes)) sustituida por la media
--             del mes sin atípicos. 0 filas si no hay estaciones SIAR o lecturas en el año.
--             Sumas de los valores diarios; un mes con días sin dato suma menos (no se rellenan huecos).
-- =============================================================================
WITH
-- Parámetros ------------------------------------------------------------------
periodo AS (
  -- [bloque periodo_hy] Año hidrológico en curso: del 1 de octubre al 30 de septiembre (fin exclusivo).
  --   Año de inicio = año actual si el mes es octubre o posterior; si no, año anterior.
  SELECT
    make_date(a.hy, 10, 1) AS inicio,
    make_date(a.hy + 1, 10, 1) AS fin
  FROM (
    SELECT
      extract(year FROM h.hoy)::int - CASE WHEN extract(month FROM h.hoy) >= 10 THEN 0 ELSE 1 END AS hy
    FROM (SELECT (now() AT TIME ZONE 'Europe/Madrid')::date AS hoy) h
  ) a
),
-- Fuentes ---------------------------------------------------------------------
-- [bloque estaciones_siar] Dispositivos activos cuyo telecontrol se llama «…SIAR…»
--   (en Odoo el tipo de telecontrol es genérico, rest; el nombre es la única marca).
estaciones AS (
  SELECT
    d.id AS dispositivo
  FROM mdm_measurement_device d
  JOIN remotecontrol t ON t.id = d.remotecontrol_id
  WHERE d.active
    AND t.name ILIKE '%siar%'
),
-- [bloque siar_diario] Sensores Et0 y Pe de las estaciones SIAR, por nombre.
sensores AS (
  SELECT
    s.id AS sensor,
    s.device_id AS dispositivo,
    lower(s.name) AS variable
  FROM mdm_measurement_device_sensor s
  JOIN estaciones e ON e.dispositivo = s.device_id
  WHERE s.active
    AND lower(s.name) IN ('et0', 'pe')
),
-- [bloque siar_diario] Valor diario por estación (día natural de Madrid); la lectura en UTC se pide
--   con un día de margen a cada lado para no perder bordes por la conversión a hora local.
lecturas_dia AS (
  SELECT
    sn.dispositivo,
    ((r.measurement_time AT TIME ZONE 'UTC') AT TIME ZONE 'Europe/Madrid')::date AS dia,
    max(r.value) FILTER (WHERE sn.variable = 'et0') AS et0,
    max(r.value) FILTER (WHERE sn.variable = 'pe') AS pe
  FROM mdm_measurement_device_sensor_reading r
  JOIN sensores sn ON sn.sensor = r.sensor_id
  WHERE r.active
    AND r.measurement_time >= (SELECT inicio - 1 FROM periodo)
    AND r.measurement_time < (SELECT fin + 1 FROM periodo)
  GROUP BY 1, 2
),
-- Transformaciones ------------------------------------------------------------
-- [bloque siar_diario] Días dentro del año hidrológico
dias_periodo AS (
  SELECT
    l.dispositivo,
    l.dia,
    l.et0,
    l.pe
  FROM lecturas_dia l
  CROSS JOIN periodo p
  WHERE l.dia >= p.inicio
    AND l.dia < p.fin
),
-- [bloque siar_diario] Mediana mensual de ET0 por estación, para detectar valores atípicos
mediana_mes AS (
  SELECT
    dispositivo,
    date_trunc('month', dia) AS mes,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY et0) AS mediana
  FROM dias_periodo
  GROUP BY 1, 2
),
-- [bloque siar_diario] ET0 atípica: > 12 mm o > max(4, 4 × mediana del mes); sin ET0 → no atípica
marcados AS (
  SELECT
    dp.dispositivo,
    dp.dia,
    dp.et0,
    dp.pe,
    coalesce(dp.et0 > 12 OR dp.et0 > greatest(4, 4 * mm.mediana), false) AS anom
  FROM dias_periodo dp
  JOIN mediana_mes mm
    ON mm.dispositivo = dp.dispositivo
    AND mm.mes = date_trunc('month', dp.dia)
),
-- [bloque siar_diario] Media mensual de ET0 sin atípicos, por estación
media_mes AS (
  SELECT
    dispositivo,
    date_trunc('month', dia) AS mes,
    avg(et0) FILTER (WHERE NOT anom) AS media
  FROM marcados
  GROUP BY 1, 2
),
-- [bloque siar_diario] ET0 atípica sustituida por la media del mes de su estación
corregidos AS (
  SELECT
    m.dispositivo,
    m.dia,
    CASE WHEN m.anom THEN me.media ELSE m.et0 END AS et0,
    m.pe,
    m.anom
  FROM marcados m
  JOIN media_mes me
    ON me.dispositivo = m.dispositivo
    AND me.mes = date_trunc('month', m.dia)
),
-- Agregados -------------------------------------------------------------------
-- [bloque siar_diario] Media diaria de todas las estaciones SIAR; anom si alguna estación lo era
diario AS (
  SELECT
    dia,
    avg(et0) AS et0,
    avg(pe) AS pe,
    bool_or(anom) AS anom
  FROM corregidos
  GROUP BY 1
),
meses AS (
  -- Los 12 meses del año hidrológico, haya o no datos
  SELECT
    generate_series(p.inicio, p.fin - interval '1 month', interval '1 month')::date AS mes
  FROM periodo p
),
totales_mes AS (
  SELECT
    me.mes,
    sum(d.et0) AS et0,
    sum(d.pe) AS pe,
    count(d.dia) AS dias
  FROM meses me
  LEFT JOIN diario d ON date_trunc('month', d.dia) = me.mes
  GROUP BY 1
),
etiqueta AS (
  -- Año hidrológico como texto AAAA-AAAA, para mostrarlo en el contenido (no en el título)
  SELECT
    to_char(inicio, 'YYYY') || '-' || to_char(fin, 'YYYY') AS anio_hidrologico
  FROM periodo
)
-- Salida ----------------------------------------------------------------------
SELECT
  (ARRAY['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'])
    [extract(month FROM mes)::int] AS mes,
  coalesce(replace(to_char(CASE WHEN dias > 0 THEN et0 END, 'FM99990.0'), '.', ','), '—') AS et0,
  coalesce(replace(to_char(CASE WHEN dias > 0 THEN pe END, 'FM99990.0'), '.', ','), '—') AS pe,
  dias,
  false AS total,
  mes AS orden,
  (SELECT anio_hidrologico FROM etiqueta) AS anio_hidrologico
FROM totales_mes
UNION ALL
-- Fila del total del año (sin GROUP BY: siempre una fila)
SELECT
  'Año',
  coalesce(replace(to_char(sum(et0), 'FM99990.0'), '.', ','), '—'),
  coalesce(replace(to_char(sum(pe), 'FM99990.0'), '.', ','), '—'),
  sum(dias)::bigint,
  true,
  (SELECT fin FROM periodo),
  (SELECT anio_hidrologico FROM etiqueta)
FROM totales_mes
ORDER BY orden"
                                    },
                                    "labels": {
                                        "grafana.app/export-label": "grafana-postgresql-datasource-1"
                                    }
                                    },
                                    "refId": "A",
                                    "hidden": false
                                }
                                }
                            ],
                            "transformations": [],
                            "queryOptions": {}
                            }
                        },
                        "vizConfig": {
                            "kind": "VizConfig",
                            "group": "marcusolsson-dynamictext-panel",
                            "version": "",
                            "spec": {
                            "options": {
                                "afterRender": "",
                                "content": "{{!-- Campos de la consulta A (una fila por mes y la del año): mes, et0, pe, total, anio_hidrologico --}}<div class="mt">{{#each data}}<div class="mt-c{{#if total}} mt-t{{/if}}"><div class="mt-m">{{mes}}</div><div class="mt-e"><em>ET<sub>0</sub></em><b>{{et0}}</b></div><div class="mt-p"><em>Pe</em><b>{{pe}}</b></div></div>{{/each}}</div><div class="mt-n">{{#each data}}{{#if total}}Año hidrológico {{anio_hidrologico}} · {{/if}}{{/each}}mm · media de las estaciones SIAR · ET<sub>0</sub> atípica sustituida por la media del mes · Pe: precipitación efectiva</div>",
                                "contentPartials": [],
                                "defaultContent": "<div class="mt-n">Sin datos SIAR en este año hidrológico.</div>",
                                "editors": [
                                "styles"
                                ],
                                "renderMode": "allRows",
                                "styles": "/* =============================================================================
   Panel 22 · totales mensuales (Business Text)
   .mt = rejilla de 13 celdas (12 meses + año) · .mt-c celda · .mt-t celda del total
   .mt-m mes · .mt-e fila ET0 · .mt-p fila Pe · .mt-n nota al pie
   ============================================================================= */
.mt{display:grid;grid-template-columns:repeat(13,minmax(0,1fr));gap:6px;font-family:Inter,Arial,sans-serif}
.mt-c{background:#f4f7f5;border-radius:10px;padding:8px 6px;text-align:center;min-width:0}
.mt-t{background:#e3eee8}
.mt-m{font-size:11px;font-weight:700;color:#33475B;letter-spacing:.3px;margin-bottom:4px}
.mt-e,.mt-p{display:flex;justify-content:space-between;gap:4px;font-size:12px;line-height:1.5}
.mt-e em,.mt-p em{font-style:normal;font-size:10px;color:#8A9BB0}
/* Subíndice del 0 de ET₀ sin alterar la altura de línea */
.mt sub,.mt-n sub{font-size:.75em;vertical-align:-.2em;line-height:0}
.mt-e b{color:#C2410C}
.mt-p b{color:#1F77B4}
.mt-n{margin-top:6px;font-size:10px;color:#8A9BB0;font-family:Inter,Arial,sans-serif}
/* Pantallas estrechas: dos filas de 7 celdas */
@media (max-width:900px){.mt{grid-template-columns:repeat(7,minmax(0,1fr))}}",
                                "wrap": false
                            },
                            "fieldConfig": {
                                "defaults": {},
                                "overrides": []
