                            }
                        }
                        }
                    },
                    "panel-23": {
                        "kind": "Panel",
                        "spec": {
                        "id": 23,
                        "title": "Temperaturas máxima y mínima",
                        "links": [],
                        "data": {
                            "kind": "QueryGroup",
                            "spec": {
                            "queries": [
                                {
                                "kind": "PanelQuery",
                                "spec": {
                                    "query": {
                                    "kind": "DataQuery",
                                    "group": "grafana-postgresql-datasource",
                                    "version": "v0",
                                    "spec": {
                                        "editorMode": "code",
                                        "format": "table",
                                        "rawQuery": true,
                                        "rawSql": "-- =============================================================================
-- Panel     : Temperaturas máxima y mínima · id 23 · ref A · table → Business Charts
-- Propósito : temperaturas máxima y mínima diarias del año hidrológico en curso (SIAR).
-- Entradas  : ninguna; año hidrológico en curso según la fecha actual (Europe/Madrid);
--             no usa variables (el dashboard público no las sustituye) ni el rango de tiempo del panel
-- Salida    : dia (texto AAAA-MM-DD), tmax (°C, 1 decimal), tmin (°C, 1 decimal)
-- Notas     : estaciones SIAR = dispositivos activos cuyo telecontrol contiene «SIAR» en el nombre;
--             sensores TempMax y TempMin por nombre; media de todas las estaciones.
--             Se omiten los días sin máxima ni mínima. 0 filas si no hay estaciones SIAR o lecturas.
-- =============================================================================
WITH
-- Parámetros ------------------------------------------------------------------
periodo AS (
  -- [bloque periodo_hy] Año hidrológico en curso: del 1 de octubre al 30 de septiembre (fin exclusivo).
  --   Año de inicio = año actual si el mes es octubre o posterior; si no, año anterior.
  SELECT
    make_date(a.hy, 10, 1) AS inicio,
    make_date(a.hy + 1, 10, 1) AS fin
  FROM (
    SELECT
      extract(year FROM h.hoy)::int - CASE WHEN extract(month FROM h.hoy) >= 10 THEN 0 ELSE 1 END AS hy
    FROM (SELECT (now() AT TIME ZONE 'Europe/Madrid')::date AS hoy) h
  ) a
),
-- Fuentes ---------------------------------------------------------------------
-- [bloque estaciones_siar] Dispositivos activos cuyo telecontrol se llama «…SIAR…»
--   (en Odoo el tipo de telecontrol es genérico, rest; el nombre es la única marca).
estaciones AS (
  SELECT
    d.id AS dispositivo
  FROM mdm_measurement_device d
  JOIN remotecontrol t ON t.id = d.remotecontrol_id
  WHERE d.active
    AND t.name ILIKE '%siar%'
),
-- [bloque siar_temperatura] Sensores TempMax y TempMin de las estaciones SIAR, por nombre.
sensores AS (
  SELECT
    s.id AS sensor,
    s.device_id AS dispositivo,
    lower(s.name) AS variable
  FROM mdm_measurement_device_sensor s
  JOIN estaciones e ON e.dispositivo = s.device_id
  WHERE s.active
    AND lower(s.name) IN ('tempmax', 'tempmin')
),
-- Valor diario por estación (día natural de Madrid), con un día de margen en la lectura UTC
lecturas_dia AS (
  SELECT
    sn.dispositivo,
    ((r.measurement_time AT TIME ZONE 'UTC') AT TIME ZONE 'Europe/Madrid')::date AS dia,
    max(r.value) FILTER (WHERE sn.variable = 'tempmax') AS tmax,
    max(r.value) FILTER (WHERE sn.variable = 'tempmin') AS tmin
  FROM mdm_measurement_device_sensor_reading r
  JOIN sensores sn ON sn.sensor = r.sensor_id
  WHERE r.active
    AND r.measurement_time >= (SELECT inicio - 1 FROM periodo)
    AND r.measurement_time < (SELECT fin + 1 FROM periodo)
  GROUP BY 1, 2
),
-- Agregados -------------------------------------------------------------------
diario AS (
  -- Media diaria de todas las estaciones SIAR, dentro del año hidrológico
  SELECT
    l.dia,
    avg(l.tmax) AS tmax,
    avg(l.tmin) AS tmin
  FROM lecturas_dia l
  CROSS JOIN periodo p
  WHERE l.dia >= p.inicio
    AND l.dia < p.fin
  GROUP BY 1
)
-- Salida ----------------------------------------------------------------------
SELECT
  to_char(dia, 'YYYY-MM-DD') AS dia,
  round(tmax::numeric, 1) AS tmax,
  round(tmin::numeric, 1) AS tmin
FROM diario
WHERE tmax IS NOT NULL
  OR tmin IS NOT NULL
ORDER BY dia"
                                    },
                                    "labels": {
                                        "grafana.app/export-label": "grafana-postgresql-datasource-1"
                                    }
                                    },
                                    "refId": "A",
                                    "hidden": false
                                }
                                }
                            ],
                            "transformations": [],
                            "queryOptions": {}
                            }
                        },
                        "vizConfig": {
                            "kind": "VizConfig",
                            "group": "volkovlabs-echarts-panel",
                            "version": "",
                            "spec": {
                            "options": {
                                "editor": {
                                "format": "auto",
                                "language": "javascript"
                                },
                                "editorMode": "code",
                                "getOption": "// =============================================================================
// Panel 23 · Temperaturas máxima y mínima (Business Charts)
// Campos: dia, tmax, tmin (ver la cabecera de la consulta A)
// Líneas de máxima y mínima con banda de amplitud, días de calor (≥ 35 °C) y de helada (≤ 0 °C),
// en la misma ventana de 3 meses que el calendario (panel 21).
// =============================================================================

// --- Datos de la consulta (format table) -------------------------------------
const f = context.panel.data.series.find(s => s.fields.some(x => x.name === 'dia'));
const g = n => (f && f.fields.find(x => x.name === n) ? Array.from(f.fields.find(x => x.name === n).values) : []);
const dia = g('dia'),
  mx0 = g('tmax').map(v => v == null ? null : Number(v)),
  mn0 = g('tmin').map(v => v == null ? null : Number(v));
// Año hidrológico de la variable oculta hy; si no se puede leer, el año hidrológico en curso
let hy = parseInt(
  context.grafana && context.grafana.replaceVariables ? context.grafana.replaceVariables('${hy}') : '',
  10
);
if (!Number.isFinite(hy)) {
  const n = new Date();
  hy = n.getMonth() >= 9 ? n.getFullYear() : n.getFullYear() - 1;
}

// --- Utilidades y estilo común -----------------------------------------------
// [bloque ventana_3_meses] Igual en los paneles 21 y 23.
// Ventana de 3 meses: termina hoy (o el 30 sep si el año ya terminó);
// si desde el 1 oct aún no han pasado 3 meses, del 1 oct al 31 dic.
const pad = n => String(n).padStart(2, '0');
const iso = d => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const hyStart = new Date(hy, 9, 1),
  hyEnd = new Date(hy + 1, 8, 30);
let wEnd = today < hyEnd ? today : hyEnd;
let wStart = new Date(wEnd.getFullYear(), wEnd.getMonth() - 3, wEnd.getDate() + 1);
if (wStart < hyStart) {
  wStart = hyStart;
  wEnd = new Date(hy, 12, 0);
}
const a = iso(wStart),
  b = iso(wEnd);

// --- Preparación -------------------------------------------------------------
// Índices de los días dentro de la ventana
const idx = dia.map((d, i) => i).filter(i => dia[i] >= a && dia[i] <= b);
if (!idx.length) return {
  title: {
    text: 'Sin datos de temperatura SIAR',
    left: 'center',
    top: 'middle',
    textStyle: { color: '#81968a', fontSize: 14, fontWeight: 500 }
  }
};
// Cada día se dibuja a mediodía para que caiga en el centro de su fecha
const t = idx.map(i => dia[i] + 'T12:00:00'),
  mx = idx.map(i => mx0[i]),
  mn = idx.map(i => mn0[i]);
const fmt = x => x == null ? '—' : Number(x).toLocaleString('es-ES', { maximumFractionDigits: 1 });
// Umbrales de calor y helada (°C)
const HOT = 35,
  FROST = 0;
// Eje Y: incluye siempre 0 °C y al menos 25 °C, con 2 °C de margen
const vmn = mn.filter(v => v != null),
  vmx = mx.filter(v => v != null);
const lo = Math.floor(Math.min(FROST + 2, ...vmn) - 2),
  hi = Math.ceil(Math.max(HOT - 10, ...vmx) + 2);

// --- Opciones ECharts --------------------------------------------------------
return {
  backgroundColor: 'transparent',
  textStyle: { fontFamily: 'Inter, Helvetica, Arial, sans-serif' },
  legend: {
    top: 0,
    itemGap: 12,
    itemWidth: 14,
    data: ['Máxima', 'Mínima', 'Calor ≥ 35 °C', 'Helada ≤ 0 °C'],
    textStyle: { color: '#33475B', fontWeight: 600, fontSize: 11 }
  },
  grid: { left: 44, right: 16, top: 40, bottom: 28 },
  tooltip: {
    trigger: 'axis',
    backgroundColor: '#fff',
    borderColor: '#C9D6E3',
    textStyle: { color: '#1B2B3A' },
    formatter: ps => {
      const i = ps[0].dataIndex;
      const d = new Date(t[i]).toLocaleDateString('es-ES',
        { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' });
      return '<b>' + d + '</b><br>Máxima: <b style="color:#C0392B">' + fmt(mx[i])
        + ' °C</b><br>Mínima: <b style="color:#1F77B4">' + fmt(mn[i])
        + ' °C</b><br>Amplitud: ' + (mx[i] == null || mn[i] == null ? '—' : fmt(mx[i] - mn[i])) + ' °C';
    }
  },
  xAxis: {
    type: 'time',
    min: a + 'T00:00:00',
    max: b + 'T23:59:59',
    axisLine: { lineStyle: { color: '#9FB3C8' } },
    axisLabel: {
      color: '#33475B',
      fontSize: 10,
      hideOverlap: true,
      // Meses en español: «Oct» el día 1, «15 Oct» el resto
      formatter: v => {
        const d = new Date(v);
        const M = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'][d.getMonth()];
        return d.getDate() === 1 ? M : d.getDate() + ' ' + M;
      }
    }
  },
  yAxis: {
    type: 'value',
    name: '°C',
    min: lo,
    max: hi,
    nameTextStyle: { color: '#33475B', fontWeight: 600 },
    axisLabel: { color: '#33475B', fontSize: 10 },
    splitLine: { lineStyle: { color: '#EEF2F6' } }
  },
  dataZoom: [{ type: 'inside' }],
  series: [
    // Banda de amplitud: serie base invisible (mínima) + rango apilado (máxima − mínima)
    {
      name: 'base',
      type: 'line',
      stack: 'r',
      data: t.map((x, i) => [x, mn[i]]),
      symbol: 'none',
      lineStyle: { opacity: 0 },
      areaStyle: { opacity: 0 },
      tooltip: { show: false },
      silent: true
    },
    {
      name: 'rango',
      type: 'line',
      stack: 'r',
      data: t.map((x, i) => [x, mx[i] == null || mn[i] == null ? null : mx[i] - mn[i]]),
      symbol: 'none',
      smooth: 0.25,
      lineStyle: { opacity: 0 },
      areaStyle: {
        color: {
          type: 'linear',
          x: 0,
          y: 0,
          x2: 0,
          y2: 1,
          colorStops: [{ offset: 0, color: 'rgba(231,76,60,0.30)' }, { offset: 1, color: 'rgba(52,152,219,0.30)' }]
        }
      },
      silent: true
    },
    {
      name: 'Máxima',
      type: 'line',
      data: t.map((x, i) => [x, mx[i]]),
      smooth: 0.25,
      symbol: 'none',
      lineStyle: { width: 2, color: '#C0392B' },
      itemStyle: { color: '#C0392B' }
    },
    {
      name: 'Mínima',
      type: 'line',
      data: t.map((x, i) => [x, mn[i]]),
      smooth: 0.25,
      symbol: 'none',
      lineStyle: { width: 2, color: '#1F77B4' },
      itemStyle: { color: '#1F77B4' }
    },
    {
      name: 'Calor ≥ 35 °C',
      type: 'scatter',
      symbolSize: 8,
      data: t.map((x, i) => mx[i] != null && mx[i] >= HOT ? [x, mx[i]] : null).filter(Boolean),
      itemStyle: { color: '#8E1B10', borderColor: '#fff', borderWidth: 1.5 }
    },
    {
      name: 'Helada ≤ 0 °C',
      type: 'scatter',
      symbol: 'diamond',
      symbolSize: 9,
      data: t.map((x, i) => mn[i] != null && mn[i] <= FROST ? [x, mn[i]] : null).filter(Boolean),
      itemStyle: { color: '#0B3C6E', borderColor: '#fff', borderWidth: 1.5 }
    },
    // Líneas de referencia de 35 °C y 0 °C (serie vacía que solo lleva markLine)
    {
      name: 'ref',
      type: 'line',
      data: [],
      markLine: {
        silent: true,
        symbol: 'none',
        data: [
          { yAxis: HOT, name: '35 °C', lineStyle: { color: '#E8A39B', type: 'dashed' } },
          { yAxis: FROST, name: '0 °C', lineStyle: { color: '#9CC3E6', type: 'dashed' } }
        ],
        label: { formatter: '{b}', position: 'insideEndTop', color: '#8A9BB0', fontSize: 10 }
      }
    }
  ]
};",
                                "renderer": "svg"
                            },
                            "fieldConfig": {
                                "defaults": {},
                                "overrides": []
                            }
                            }
                        }
                        }
